  45	def _parse_proxy_list() -> list[ProxyEntry]:
  46	    raw = os.environ.get("PROXY_LIST", "")
  47	    if not raw:
  48	        current = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY")
  49	        if current:
  50	            return [ProxyEntry(id="default", name="Default", url=current)]
  51	        return []
  52	    entries = []
  53	    for item in raw.split(","):
  54	        item = item.strip()
  55	        if not item:
  56	            continue
  57	        if "|" in item:
  58	            parts = item.split("|", 2)
  59	            pid = parts[0].strip().lower().replace(" ", "-")
  60	            name = parts[0].strip()
  61	            url = parts[1].strip()
  62	        else:
  63	            url = item
  64	            pid = url.split(":")[-1] if ":" in url else "proxy"
  65	            name = url
  66	        # Stable id for direct — name-derived id mangles cyrillic/parens
  67	        # ("Direct (VPN/Соту)" → "direct-(vpn/соту)")
  68	        if url == "direct":
  69	            pid = "direct"
  70	        entries.append(ProxyEntry(id=pid, name=name, url=url))
  71	    return entries
