  74	def _active_id(entries: list[ProxyEntry]) -> str:
  75	    """Which entry matches the current HTTPS_PROXY (from .env). Read-only."""
  76	    current = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY") or ""
  77	    if not current:
  78	        direct = next((e for e in entries if e.url == "direct"), None)
  79	        return direct.id if direct else ""
  80	    match = next((e for e in entries if e.url == current), None)
  81	    return match.id if match else ""
